SET client_encoding = 'UTF8';
































































































































































ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('era', 'id'), COALESCE((SELECT MAX(id) FROM era), 1));
SELECT setval(pg_get_serial_sequence('attribute', 'id'), COALESCE((SELECT MAX(id) FROM attribute), 1));
SELECT setval(pg_get_serial_sequence('summonmechanic', 'id'), COALESCE((SELECT MAX(id) FROM summonmechanic), 1));
