SELECT setval(pg_get_serial_sequence('card_type', 'id'), COALESCE((SELECT MAX(id) FROM card_type), 1));
SELECT setval(pg_get_serial_sequence('card_status', 'id'), COALESCE((SELECT MAX(id) FROM card_status), 1));
