INSERT INTO card (id, name, img_url, description, level, atk, def, attribute, type, card_type) VALUES
('80570228', 'Anarchist Monk of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/80570228.jpg', 'If you control a "Six Samurai" monster other than "Anarchist Monk of the Six Samurai", you can Special Summon this card (from your hand). You can only Special Summon "Anarchist Monk of the Six Samurai" once per turn this way. You can only use each of the following effects of "Anarchist Monk of the Six Samurai" once per turn. If this card is sent from the field to the GY: You can add 1 "Six Samurai" Quick-Play Spell from your Deck to your hand. A "Six Samurai" monster that was Synchro Summoned using this card gains this effect. The Levels of all monsters your opponent controls are reduced by 1.', '3', '500', '0', 'DARK', 'Warrior', 'Tuner Monster'),
('27821104', 'Asceticism of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/27821104.jpg', 'Target 1 "Six Samurai" monster you control; Special Summon 1 "Six Samurai" monster from your Deck with the same ATK but a different name, and if you do, destroy it during the End Phase of this turn.', NULL, NULL, NULL, NULL, NULL, 'Quick-Play Spell'),
('74752631', 'Battle Shogun of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/74752631.jpg', '2 Warrior monsters, including a "Six Samurai" monster. If this card is Link Summoned: You can discard 1 card; add 1 card from your Deck to your hand that has an effect that places a Bushido Counter(s). You can only use this effect of "Battle Shogun of the Six Samurai" once per turn. Each time a "Six Samurai" monster(s) is Normal or Special Summoned to a zone(s) this card points to, place 1 Bushido Counter on this card. Gains 100 ATK for each Bushido Counter on your field.', NULL, '1000', NULL, 'EARTH', 'Warrior', 'Link Monster'),
('44430454', 'Chamberlain of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/44430454.jpg', 'The Six Samurai are supported from the shadows by this silent and mysterious warrior. His past is unknown to them, but his countless scars are proof of his experience.', '3', '200', '2000', 'EARTH', 'Warrior', 'Normal Monster'),
('27178262', 'Cunning of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/27178262.jpg', 'Send 1 face-up "Six Samurai" monster you control to the Graveyard, then target 1 "Six Samurai" monster in either player''s Graveyard; Special Summon that target.', NULL, NULL, NULL, NULL, NULL, 'Quick-Play Spell'),
('61737116', 'Elder of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/61737116.jpg', 'If your opponent controls a monster and you control no monsters, you can Special Summon this card (from your hand).', '3', '400', '0', 'EARTH', 'Warrior', 'Effect Monster'),
('27970830', 'Gateway of the Six', 'https://images.ygoprodeck.com/images/cards/27970830.jpg', 'Each time a "Six Samurai" monster(s) is Normal or Special Summoned, place 2 Bushido Counters on this card. You can remove Bushido Counters from your field to activate these effects. 2 Counters: Target 1 "Six Samurai" or "Shien" Effect Monster; that target gains 500 ATK until the end of this turn. 4 Counters: Add 1 "Six Samurai" monster from your Deck or GY to your hand. 6 Counters: Target 1 "Shien" Effect Monster in your GY; Special Summon that target.', NULL, NULL, NULL, NULL, NULL, 'Continuous Spell'),
('83039729', 'Grandmaster of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/83039729.jpg', 'While you control another "Six Samurai" monster with a different name, this card gains 500 ATK and DEF. If this card would be destroyed, you can destroy another "Six Samurai" monster you control instead.', '5', '2100', '800', 'EARTH', 'Warrior', 'Effect Monster'),
('78792195', 'Great Shogun Shien', 'https://images.ygoprodeck.com/images/cards/78792195.jpg', 'If you control a face-up "Six Samurai" monster(s), you can Special Summon this card (from your hand). Your opponent can only activate 1 Spell/Trap Card per turn.', '7', '2500', '2400', 'EARTH', 'Warrior', 'Effect Monster'),
('1498130', 'Hand of the Six Samurai', 'https://images.ygoprodeck.com/images/cards/1498130.jpg', 'If you control another "Six Samurai" monster: You can Tribute 1 "Six Samurai" monster, then target 1 monster on the field; destroy it.', '3', '1600', '1000', 'FIRE', 'Warrior', 'Effect Monster'),
('70634245', 'Legendary Six Samurai - Enishi', 'https://images.ygoprodeck.com/images/cards/70634245.jpg', 'Once per turn, during either player''s turn: You can banish 2 "Six Samurai" monsters from your Graveyard to target 1 face-up monster on the field; banish it until the End Phase.', '4', '1700', '700', 'LIGHT', 'Warrior', 'Effect Monster'),
('42209438', 'Legendary Six Samurai - Kageki', 'https://images.ygoprodeck.com/images/cards/42209438.jpg', 'If you control a face-up "Six Samurai" monster other than "Legendary Six Samurai - Kageki", you can Special Summon this card (from your hand).', '4', '200', '2000', 'EARTH', 'Warrior', 'Effect Monster'),
('34235530', 'Legendary Six Samurai - Kizan', 'https://images.ygoprodeck.com/images/cards/34235530.jpg', 'If you control a face-up "Six Samurai" monster other than "Legendary Six Samurai - Kizan", you can Special Summon this card (from your hand).', '4', '1800', '500', 'EARTH', 'Warrior', 'Effect Monster'),
('15327215', 'Legendary Six Samurai - Mizuho', 'https://images.ygoprodeck.com/images/cards/15327215.jpg', 'If you control a face-up "Six Samurai" monster other than "Legendary Six Samurai - Mizuho", you can Special Summon this card (from your hand). Once per turn: You can target 1 "Six Samurai" monster other than "Legendary Six Samurai - Mizuho"; destroy it, and if you do, banish it.', '3', '1600', '1000', 'FIRE', 'Warrior', 'Effect Monster'),
('75116619', 'Legendary Six Samurai - Shinai', 'https://images.ygoprodeck.com/images/cards/75116619.jpg', 'If you control a face-up "Legendary Six Samurai - Shinai", you can Special Summon this card (from your hand).', '3', '1500', '1500', 'WATER', 'Warrior', 'Effect Monster'),
('2511717', 'Legendary Six Samurai - Shi En', 'https://images.ygoprodeck.com/images/cards/2511717.jpg', '1 Tuner + 1+ non-Tuner "Six Samurai" monsters Once per turn, when your opponent would activate a Spell/Trap Card: You can negate the activation and destroy it. If this card is destroyed by card effect: You can target 1 "Six Samurai" monster in your GY; Special Summon that target.', '5', '2500', '1400', 'WIND', 'Warrior', 'Synchro Monster'),
('49721904', 'Secret Six Samurai - Doji', 'https://images.ygoprodeck.com/images/cards/49721904.jpg', 'If you control a "Six Samurai" monster: You can Special Summon this card from your hand. You can only use this effect of "Secret Six Samurai - Doji" once per turn.', '4', '400', '1800', 'WIND', 'Warrior', 'Effect Monster'),
('74094021', 'Secret Six Samurai - Fuma', 'https://images.ygoprodeck.com/images/cards/74094021.jpg', 'If this card is sent to the GY: You can target 1 "Six Samurai" monster in your GY, except "Secret Six Samurai - Fuma"; Special Summon it. If this card is sent to the GY for the Synchro Summon of a "Six Samurai" monster: You can send 1 "Six Samurai" monster from your Deck to the GY, then target 1 "Shien" Effect Monster in your GY; Special Summon it.', '1', '200', '1800', 'WIND', 'Warrior', 'Tuner Monster'),
('29981921', 'Secret Six Samurai - Genba', 'https://images.ygoprodeck.com/images/cards/29981921.jpg', 'If this card is Normal Summoned: You can target 1 "Six Samurai" card in your GY; add it to your hand, but banish it when it leaves the field. If exactly 1 "Six Samurai" monster you control (and no other cards) would be destroyed by a card effect, you can banish this card from your GY instead.', '3', '600', '1600', 'EARTH', 'Warrior', 'Effect Monster'),
('27744077', 'Absolute End', 'https://images.ygoprodeck.com/images/cards/27744077.jpg', 'Activate only during your opponent''s turn. This turn, the attacks from your opponent''s monsters become direct attacks.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('48505422', 'Secret Six Samurai - Kizaru', 'https://images.ygoprodeck.com/images/cards/48505422.jpg', 'If you control a "Six Samurai" monster: You can Special Summon this card from your hand. If you control exactly 3 "Six Samurai" monsters with different Attributes: You can target 1 card on the field; destroy it.', '4', '1900', '800', 'EARTH', 'Warrior', 'Effect Monster'),
('93368494', 'Mayosenju Daibak', 'https://images.ygoprodeck.com/images/cards/93368494.jpg', 'Cannot be Special Summoned, except by Pendulum Summon. This card''s Pendulum Summon cannot be negated. If this card is Normal or Special Summoned: You can target up to 2 cards on the field; return them to the hand. Once per turn, during the End Phase, if this card was Special Summoned this turn: Return it to the hand.', '10', '3000', '300', 'WIND', 'Beast', 'Pendulum Effect Monster'),
('21364070', 'Mayosenju Hitot', 'https://images.ygoprodeck.com/images/cards/21364070.jpg', 'Cannot be Special Summoned, except by Pendulum Summon. If this card is Normal or Special Summoned: You can target 1 card your opponent controls; return it to the hand. Each time a card(s) on the field is returned to the hand or Main Deck by your card effect, while this card is on the field: All "Yosenju" monsters you currently control gain 500 ATK. Once per turn, during the End Phase, if this card was Special Summoned this turn: Return it to the hand.', '10', '2000', '3000', 'WIND', 'Beast', 'Pendulum Effect Monster'),
('85970321', 'Yosenju Izna', 'https://images.ygoprodeck.com/images/cards/85970321.jpg', 'Once per turn, during the End Phase, if this card was Normal Summoned this turn: Return it to the hand. You can only use each of the following effects of "Yosenju Izna" once per turn. You can discard this card; this turn, your opponent cannot activate cards or effects when a "Yosenju" monster(s) is Normal or Special Summoned. If you control another "Yosenju" monster: You can draw 1 card.', '4', '800', '1200', 'WIND', 'Beast', 'Effect Monster'),
('65247798', 'Yosenju Kama 1', 'https://images.ygoprodeck.com/images/cards/65247798.jpg', 'Once per turn, during the End Phase, if this card was Normal Summoned this turn: Return it to the hand. If this card is Normal Summoned, you can: Immediately after this effect resolves, Normal Summon 1 "Yosenju" monster from your hand, except "Yosenju Kama 1". If you control another "Yosenju" monster: You can target 1 face-up card your opponent controls; return it to the hand.', '4', '1600', '500', 'WIND', 'Beast', 'Effect Monster'),
('92246806', 'Yosenju Kama 2', 'https://images.ygoprodeck.com/images/cards/92246806.jpg', 'If this card is Normal Summoned, you can: Immediately after this effect resolves, Normal Summon 1 "Yosenju" monster from your hand, except "Yosenju Kama 2". If you control another "Yosenju" monster: You can target 1 card in your opponent''s Graveyard; banish it, and if you do, this card gains 500 ATK until the end of this turn. Once per turn, during the End Phase, if this card was Normal Summoned this turn: Return it to the hand.', '4', '1800', '200', 'WIND', 'Beast', 'Effect Monster'),
('28630501', 'Yosenju Kama 3', 'https://images.ygoprodeck.com/images/cards/28630501.jpg', 'If this card is Normal Summoned, you can: Immediately after this effect resolves, Normal Summon 1 "Yosenju" monster from your hand, except "Yosenju Kama 3". If this card is destroyed by battle or card effect and sent to the Graveyard: You can target 1 "Yosenju" card in your Graveyard, except "Yosenju Kama 3"; add it to your hand. Once per turn, during the End Phase, if this card was Normal Summoned this turn: Return it to the hand.', '4', '1700', '100', 'WIND', 'Beast', 'Effect Monster'),
('23740893', 'Yosenju Oyam', 'https://images.ygoprodeck.com/images/cards/23740893.jpg', 'When this card is Normal Summoned: You can Special Summon 1 Level 5 or higher "Yosenju" monster from your hand, but it has its effects negated (if any). Once per turn: You can banish 1 "Yosenju" card from your Graveyard, then target 1 face-up card on the field; destroy it.', '6', '1900', '0', 'WIND', 'Beast', 'Effect Monster'),
('49249907', 'Yosenju Sabu', 'https://images.ygoprodeck.com/images/cards/49249907.jpg', 'If you control no other monsters: You can Special Summon this card from your hand. A "Yosenju" monster that was Special Summoned this way cannot be used as Synchro Material. If this card is Special Summoned: You can add 1 "Yosenju" Pendulum Monster from your Deck to your hand. You can only use each effect of "Yosenju Sabu" once per turn.', '4', '1800', '400', 'WIND', 'Beast', 'Effect Monster'),
('61884774', 'Yosenjus Shinchu R', 'https://images.ygoprodeck.com/images/cards/61884774.jpg', 'While you have another "Yosenju" card in your Pendulum Zone: You can target 1 "Yosenju" monster you control; it gains 500 ATK for each "Yosenju" card in your Pendulum Zones (even if this card leaves the field). Once per turn, during the End Phase, if this card was Normal Summoned this turn: Return it to the hand.', '4', '1000', '0', 'WIND', 'Beast', 'Effect Monster'),
('69838592', 'Yosenjus Shinchu L', 'https://images.ygoprodeck.com/images/cards/69838592.jpg', 'While you have another "Yosenju" card in your Pendulum Zone: You can Special Summon this card from your hand. You can only use this effect of "Yosenjus Shinchu L" once per turn. Once per turn, during the End Phase, if this card was Normal or Special Summoned this turn: Return it to the hand.', '4', '1000', '0', 'WIND', 'Beast', 'Effect Monster'),
('58981727', 'Yosenju Tsujik', 'https://images.ygoprodeck.com/images/cards/58981727.jpg', 'Once per turn, during the End Phase, if this card was Normal Summoned this turn: Return it to the hand. If this card is discarded: You can add 1 "Yosenju" card from your Deck to your hand, except "Yosenju Tsujik". You can only use this effect of "Yosenju Tsujik" once per turn. If this card is sent to the Graveyard: You can target 1 card your opponent controls; return it to the hand.', '4', '1000', '1000', 'WIND', 'Beast', 'Effect Monster'),
('65025250', 'Yosen Whirlwind', 'https://images.ygoprodeck.com/images/cards/65025250.jpg', 'Activate this card by paying 800 LP. Once per turn, if a face-up "Yosenju" monster you control returns to the hand (except during the Damage Step): You can target 1 card your opponent controls; return it to the hand. During your End Phase, unless this effect was activated this turn (and was not negated), destroy this card.', NULL, NULL, NULL, NULL, NULL, 'Continuous Spell'),
('91420254', 'Yosen Training Grounds', 'https://images.ygoprodeck.com/images/cards/91420254.jpg', 'Each time a "Yosenju" monster(s) is Normal or Special Summoned, place 1 Yosen Counter on this card. You can remove any number of Yosen Counters from this card; apply this effect, depending on the number of Yosen Counters removed. You can only use this effect of "Yosen Training Grounds" once per turn. 1 Counter: All "Yosenju" monsters you currently control gain 300 ATK until the end of this turn. 3 Counters: Add 1 "Yosenju" card from your Deck or Graveyard to your hand.', NULL, NULL, NULL, NULL, NULL, 'Continuous Spell'),
('54903668', 'Dizzying Winds of Yosen Village', 'https://images.ygoprodeck.com/images/cards/54903668.jpg', 'Activate this card only if you control a Level 6 or higher "Yosenju" monster. While you have a "Yosenju" card in your Pendulum Zone, if a monster would be returned from the field to the hand by a card effect, shuffle it into the Deck instead, unless it is a "Yosenju" monster.', NULL, NULL, NULL, NULL, NULL, 'Continuous Trap'),
('10612222', 'Yosenju Shinchu', 'https://images.ygoprodeck.com/images/cards/10612222.jpg', 'If this card is destroyed by battle or card effect: You can Special Summon 1 "Yosenju" monster from your Deck, except "Yosenju Shinchu". Once per turn, during the End Phase, if this card was Normal Summoned this turn: Return it to the hand.', '4', '600', '1800', 'WIND', 'Beast', 'Effect Monster'),
('25244515', 'Yosenjus Thundering Bow', 'https://images.ygoprodeck.com/images/cards/25244515.jpg', 'Activate only while you control a "Yosenju" monster. While you have at least 1 "Yosenju" card in your Pendulum Zone, each time a card(s) is shuffled from the field into its owner''s Deck by a card effect: Target 1 card your opponent controls; destroy it.', NULL, NULL, NULL, NULL, NULL, 'Continuous Trap'),
('54880296', 'Yosenjus Hornet', 'https://images.ygoprodeck.com/images/cards/54880296.jpg', 'If this card is destroyed by battle or card effect and sent to the Graveyard: You can add 1 "Yosenju" Pendulum Monster from your Deck to your hand. If a "Yosenju" monster(s) you control would be destroyed by battle, you can destroy this card instead.', '4', '1800', '300', 'WIND', 'Beast', 'Effect Monster'),
('39853199', 'Yosen Judgment', 'https://images.ygoprodeck.com/images/cards/39853199.jpg', 'Target 1 "Yosenju" monster you control; return it to the hand, and if you do, Special Summon 1 "Yosenju" Pendulum Monster from your Deck with a different name from that monster.', NULL, NULL, NULL, NULL, NULL, 'Quick-Play Spell'),
('62681049', 'Yosen Secret Move', 'https://images.ygoprodeck.com/images/cards/62681049.jpg', 'When your opponent''s monster declares a direct attack: Banish 1 "Yosenju" monster from your Graveyard; negate the attack, then if you control no monsters, you can Special Summon 1 "Yosenju" monster from your Deck.', NULL, NULL, NULL, NULL, NULL, 'Normal Trap'),
('44335251', 'Animadorned Archosaur', 'https://images.ygoprodeck.com/images/cards/44335251.jpg', 'If this card is Normal or Special Summoned: You can destroy 1 Dinosaur monster in your hand or face-up field, except "Animadorned Archosaur", then add 1 Reptile, Sea Serpent, or Winged Beast monster with the same original Level as that destroyed monster, OR 1 "Evolution Pill" Spell, from your Deck to your hand. You can only use this effect of "Animadorned Archosaur" once per turn.', '1', '0', '0', 'LIGHT', 'Dinosaur', 'Effect Monster'),
('36042004', 'Babycerasaurus', 'https://images.ygoprodeck.com/images/cards/36042004.jpg', 'If this card is destroyed by a card effect and sent to the Graveyard: Special Summon 1 Level 4 or lower Dinosaur-Type monster from your Deck.', '2', '500', '500', 'EARTH', 'Dinosaur', 'Effect Monster'),
('82946847', 'Jurrac Guaiba', 'https://images.ygoprodeck.com/images/cards/82946847.jpg', 'If this card destroys an opponent''s monster by battle: You can Special Summon 1 "Jurrac" monster with 1700 or less ATK from your Deck in face-up Defense Position.', '4', '1700', '400', 'FIRE', 'Dinosaur', 'Effect Monster'),
('18940556', 'Jurrac Stauriko', 'https://images.ygoprodeck.com/images/cards/18940556.jpg', 'When this card is destroyed by battle and sent to the Graveyard: You can activate this effect: Special Summon 1 Level 4 or lower "Jurrac" monster from your Deck in face-up Defense Position.', '2', '500', '400', 'FIRE', 'Dinosaur', 'Effect Monster'),
('58272005', 'Jurrac Titano', 'https://images.ygoprodeck.com/images/cards/58272005.jpg', 'Cannot be Normal Summoned/Set. Must be Special Summoned by its own effect and cannot be Special Summoned in other ways. When a "Jurrac" monster you control, except "Jurrac Titano", is destroyed by battle with an opponent''s monster and sent to the Graveyard: You can Special Summon this card from your hand. This card is not affected by other cards'' effects. At the end of your opponent''s Battle Phase, if this card attacked or was attacked: Return this card to the hand.', '11', '3000', '2800', 'FIRE', 'Dinosaur', 'Effect Monster'),
('44612603', 'Jurrac Velphito', 'https://images.ygoprodeck.com/images/cards/44612603.jpg', 'If this card destroys an opponent''s monster by battle: You can Special Summon 1 "Jurrac" monster from your Deck except "Jurrac Velphito".', '4', '1700', '300', 'FIRE', 'Dinosaur', 'Effect Monster'),
('98022050', 'Jurrac Gallim', 'https://images.ygoprodeck.com/images/cards/98022050.jpg', 'When this card is destroyed by battle and sent to the Graveyard: Special Summon 1 "Jurrac" Tuner monster from your Deck in face-up Defense Position.', '1', '0', '0', 'FIRE', 'Dinosaur', 'Effect Monster'),
('58272008', 'Ultimate Tyranno', 'https://images.ygoprodeck.com/images/cards/58272008.jpg', 'This card can attack all monsters your opponent controls once each. If this card attacks a Defense Position monster, inflict piercing battle damage to your opponent.', '10', '3000', '2000', 'LIGHT', 'Dinosaur', 'Effect Monster'),
('27553701', 'Absolute King - Megaplunder', 'https://images.ygoprodeck.com/images/cards/27553701.jpg', 'The king of dinosaurs that rules over the Earth. Its mighty roar makes its foes tremble in fear!', '6', '2000', '1500', 'EARTH', 'Dinosaur', 'Normal Monster'),
('12580477', 'Fossil Dig', 'https://images.ygoprodeck.com/images/cards/12580477.jpg', 'Add 1 Level 6 or lower Dinosaur-Type monster from your Deck to your hand.', NULL, NULL, NULL, NULL, NULL, 'Normal Spell'),
('15693423', 'Miscellaneousaurus', 'https://images.ygoprodeck.com/images/cards/15693423.jpg', 'Banish 1 Dinosaur-Type monster from your Graveyard; Special Summon 1 Level 4 or lower Dinosaur-Type monster from your Deck.', NULL, NULL, NULL, NULL, NULL, 'Normal Spell'),
('12580478', 'Survival of the Fittest', 'https://images.ygoprodeck.com/images/cards/12580478.jpg', 'Destroy this card during your 3rd End Phase after activation. While this card is face-up on the field, all Dinosaur-Type monsters you control gain 300 ATK.', NULL, NULL, NULL, NULL, NULL, 'Continuous Spell'),
('36042005', 'Jurrac Impact', 'https://images.ygoprodeck.com/images/cards/36042005.jpg', 'When a Dinosaur-Type monster you control is destroyed by battle and sent to the Graveyard: Destroy the monster that destroyed it.', NULL, NULL, NULL, NULL, NULL, 'Normal Trap'),
('82946848', 'Jurrac Fury', 'https://images.ygoprodeck.com/images/cards/82946848.jpg', 'Target face-up "Jurrac" monsters you control; they gain ATK equal to their Level x 200 until the End Phase.', NULL, NULL, NULL, NULL, NULL, 'Normal Trap'),
('44335252', 'Jurrac Meteor', 'https://images.ygoprodeck.com/images/cards/44335252.jpg', 'Target 1 Dinosaur-Type Synchro Monster you control; Special Summon 1 non-Synchro "Jurrac" monster from your Graveyard, but destroy it during the End Phase of this turn.', NULL, NULL, NULL, NULL, NULL, 'Quick-Play Spell'),
('36042006', 'Jurrac Aeolo', 'https://images.ygoprodeck.com/images/cards/36042006.jpg', 'If you control a "Jurrac" monster: You can Special Summon this card (from your hand).', '1', '200', '400', 'FIRE', 'Dinosaur', 'Tuner Monster'),
('82946849', 'Jurrac Velo', 'https://images.ygoprodeck.com/images/cards/82946849.jpg', 'If this card is destroyed by a card effect: You can Special Summon 1 Level 4 or lower "Jurrac" monster from your GY, except "Jurrac Velo".', '3', '1700', '400', 'FIRE', 'Dinosaur', 'Effect Monster'),
('18940557', 'Jurrac Protector', 'https://images.ygoprodeck.com/images/cards/18940557.jpg', 'While you control a face-up "Jurrac" monster, this card cannot be destroyed by battle or by card effects.', '4', '1800', '600', 'FIRE', 'Dinosaur', 'Effect Monster'),
('58272006', 'Jurrac Ptera', 'https://images.ygoprodeck.com/images/cards/58272006.jpg', 'When this card is destroyed by battle and sent to the Graveyard: All face-up monsters your opponent controls lose 800 ATK.', '3', '800', '1500', 'FIRE', 'Dinosaur', 'Effect Monster'),
('44612604', 'Jurrac Dino', 'https://images.ygoprodeck.com/images/cards/44612604.jpg', 'If this card destroys an opponent''s monster by battle: You can Special Summon 1 "Jurrac" monster from your hand or Graveyard.', '4', '1700', '800', 'FIRE', 'Dinosaur', 'Effect Monster'),
('40387124', 'Abyss Flower', 'https://images.ygoprodeck.com/images/cards/40387124.jpg', '''''A rarely seen flower that blossoms quietly on the edge of darkness.''''', '2', '750', '400', 'EARTH', NULL, 'Normal Monster'),
('80181649', '"A Case for K9"', 'https://images.ygoprodeck.com/images/cards/80181649.jpg', 'When this card is activated: You can add 1 "K9" monster from your Deck to your hand. "K9" monsters you control gain 900 ATK during any turn in which your opponent has activated a monster effect in the hand or GY. If this card in the Spell & Trap Zone is destroyed by card effect: You can Set 1 "K9" Quick-Play Spell from your Deck or GY. You can only use this effect of ""A Case for K9"" once per turn. You can only activate 1 ""A Case for K9"" per turn.', '0', '0', '0', NULL, NULL, 'Continuous Spell'),
('34541863', '"A" Cell Breeding Device', 'https://images.ygoprodeck.com/images/cards/34541863.jpg', 'During each of your Standby Phases, put 1 A-Counter on 1 face-up monster your opponent controls.', '0', '0', '0', NULL, NULL, 'Continuous Spell'),
('64163367', '"A" Cell Incubator', 'https://images.ygoprodeck.com/images/cards/64163367.jpg', 'Each time an A-Counter(s) is removed from play by a card effect, place 1 A-Counter on this card. When this card is destroyed, distribute the A-Counters on this card among face-up monsters.', '0', '0', '0', NULL, NULL, 'Continuous Spell'),
('91231901', '"A" Cell Recombination Device', 'https://images.ygoprodeck.com/images/cards/91231901.jpg', 'Target 1 face-up monster on the field; send 1 "Alien" monster from your Deck to the Graveyard, and if you do, place A-Counters on that monster equal to the Level of the sent monster. During your Main Phase, except the turn this card was sent to the Graveyard: You can banish this card from your Graveyard; add 1 "Alien" monster from your Deck to your hand.', '0', '0', '0', NULL, NULL, 'Quick-Play Spell'),
('73262676', '"A" Cell Scatter Burst', 'https://images.ygoprodeck.com/images/cards/73262676.jpg', 'Select 1 face-up "Alien" monster you control. Destroy it and distribute new A-Counters equal to its Level among your opponent''s face-up monsters.', '0', '0', '0', NULL, NULL, 'Quick-Play Spell'),
('98319530', '"Infernoble Arms - Almace"', 'https://images.ygoprodeck.com/images/cards/98319530.jpg', 'While this card is equipped to a monster: You can equip 1 "Infernoble Arms" Equip Spell from your Deck or GY, except ""Infernoble Arms - Almace"", to 1 appropriate monster you control, then destroy this card. If this card is sent to the GY because the equipped monster is sent to the GY: You can target 1 of your FIRE Warrior monsters that is banished or in your GY; add it to your hand. You can only use 1 ""Infernoble Arms - Almace"" effect per turn, and only once that turn.', '0', '0', '0', NULL, NULL, 'Equip Spell'),
('37478723', '"Infernoble Arms - Durendal"', 'https://images.ygoprodeck.com/images/cards/37478723.jpg', 'While this card is equipped to a monster: You can add 1 Level 5 or lower FIRE Warrior monster from your Deck to your hand, then destroy this card. If this card is sent to the GY because the equipped monster is sent to the GY: You can target 1 Level 5 or lower FIRE Warrior monster in your GY; Special Summon it, also you cannot Special Summon monsters for the rest of the turn, except Warrior monsters. You can only use 1 ""Infernoble Arms - Durendal"" effect per turn, and only once that turn.', '0', '0', '0', NULL, NULL, 'Equip Spell'),
('64867422', '"Infernoble Arms - Hauteclere"', 'https://images.ygoprodeck.com/images/cards/64867422.jpg', 'While this card is equipped to a monster: You can target 1 face-up monster you control; this turn, you cannot declare attacks, except with that monster, also it gains the ability this turn to make a second attack during each Battle Phase, then destroy this card. If this card is sent to the GY because the equipped monster is sent to the GY: You can target 1 face-up monster on the field; destroy it. You can only use 1 ""Infernoble Arms - Hauteclere"" effect per turn, and only once that turn.', '0', '0', '0', NULL, NULL, 'Equip Spell'),
('90861137', '"Infernoble Arms - Joyeuse"', 'https://images.ygoprodeck.com/images/cards/90861137.jpg', 'While this card is equipped to a monster: You can target 1 FIRE Warrior monster in your GY; add it to your hand, then destroy this card. If this card is sent to the GY because the equipped monster is sent to the GY: You can Special Summon 1 FIRE Warrior monster from your hand. You can only use 1 ""Infernoble Arms - Joyeuse"" effect per turn, and only once that turn.', '0', '0', '0', NULL, NULL, 'Equip Spell'),
('44256816', '1st Movement Solo', 'https://images.ygoprodeck.com/images/cards/44256816.jpg', 'If you control no monsters: Special Summon 1 Level 4 or lower "Melodious" monster from your hand or Deck. You can only activate 1 "1st Movement Solo" per turn. You cannot Special Summon monsters during the turn you activate this card, except "Melodious" monsters.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('86988864', '3-Hump Lacooda', 'https://images.ygoprodeck.com/images/cards/86988864.jpg', 'If there are 3 face-up "3-Hump Lacooda" cards on your side of the field, Tribute 2 of them to draw 3 cards.', '3', '500', '1500', 'EARTH', NULL, 'Effect Monster'),
('11714098', '30,000-Year White Turtle', 'https://images.ygoprodeck.com/images/cards/11714098.jpg', '''''A huge turtle that has existed for over 30,000 years.''''', '5', '1250', '2100', 'WATER', NULL, 'Normal Monster'),
('83994646', '4-Starred Ladybug of Doom', 'https://images.ygoprodeck.com/images/cards/83994646.jpg', 'FLIP: Destroy all Level 4 monsters your opponent controls.', '3', '800', '1200', 'WIND', NULL, 'Flip Effect Monster'),
('67048711', '7', 'https://images.ygoprodeck.com/images/cards/67048711.jpg', 'When there are 3 face-up "7" cards on your side of the field, draw 3 cards from your Deck. Then destroy all "7" cards. When this card is sent directly from the field to your Graveyard, increase your Life Points by 700 points.', '0', '0', '0', NULL, NULL, 'Continuous Spell'),
('23771716', '7 Colored Fish', 'https://images.ygoprodeck.com/images/cards/23771716.jpg', 'A rare rainbow fish that has never been caught by mortal man.', '4', '1800', '800', 'WATER', NULL, 'Normal Monster'),
('86198326', '7 Completed', 'https://images.ygoprodeck.com/images/cards/86198326.jpg', 'Activate this card by choosing ATK or DEF; equip only to a Machine monster. It gains 700 ATK or DEF, depending on the choice.', '0', '0', '0', NULL, NULL, 'Equip Spell'),
('14261867', '8-Claws Scorpion', 'https://images.ygoprodeck.com/images/cards/14261867.jpg', 'Once per turn, you can flip this card into face-down Defense Position. When this card attacks an opponent''s face-down Defense Position monster, this card''s ATK becomes 2400 during damage calculation only.', '2', '300', '200', 'DARK', NULL, 'Effect Monster'),
('4731783', 'A Bao A Qu, the Lightless Shadow', 'https://images.ygoprodeck.com/images/cards/4731783.jpg', '2+ monsters, including a Fiend monster\\r\\nDuring the Main Phase (Quick Effect): You can discard 1 card, then activate 1 of these effects;\\r\\n● Destroy 1 card on the field.\\r\\n● Banish this card (until the End Phase), and if you do, Special Summon 1 LIGHT or DARK monster from your GY.\\r\\nDuring your Standby Phase: You can draw cards equal to the number of different Monster Types in your GY, then place cards from your hand on the bottom of the Deck in any order, equal to the number of cards you drew. You can only use each effect of "A Bao A Qu, the Lightless Shadow" once per turn.', '0', '2800', '0', 'DARK', NULL, 'Link Monster'),
('24140059', 'A Cat of Ill Omen', 'https://images.ygoprodeck.com/images/cards/24140059.jpg', 'FLIP: Choose 1 Trap from your Deck and place it on top of your Deck, or, if "Necrovalley" is on the field, you can add that Trap to your hand instead.', '2', '500', '300', 'DARK', NULL, 'Flip Effect Monster'),
('43905751', 'Madjinn Gunn', 'https://images.ygoprodeck.com/images/cards/43905751.jpg', '''''A living weapon that spits projectiles.''''', '2', '600', '800', 'DARK', NULL, 'Normal Monster'),
('6850209', 'A Deal with Dark Ruler', 'https://images.ygoprodeck.com/images/cards/6850209.jpg', '(This card is always treated as an "Archfiend" card.)\\nIf a Level 8 or higher monster under your control was sent to the Graveyard this turn: Special Summon 1 "Berserk Dragon" from your hand or Deck.', '0', '0', '0', NULL, NULL, 'Quick-Play Spell'),
('49140998', 'A Feather of the Phoenix', 'https://images.ygoprodeck.com/images/cards/49140998.jpg', 'Discard 1 card, then target 1 card in your GY; return that target to the top of your Deck.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('68170903', 'A Feint Plan', 'https://images.ygoprodeck.com/images/cards/68170903.jpg', 'A player cannot attack face-down monsters during this turn.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('21597117', 'A Hero Emerges', 'https://images.ygoprodeck.com/images/cards/21597117.jpg', 'When an opponent''s monster declares an attack: Your opponent chooses 1 random card from your hand, then if it is a monster that can be Special Summoned, Special Summon it. Otherwise, send it to the Graveyard.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('8949584', 'A Hero Lives', 'https://images.ygoprodeck.com/images/cards/8949584.jpg', 'If you control no face-up monsters: Pay half your LP; Special Summon 1 Level 4 or lower "Elemental HERO" monster from your Deck.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('295517', 'A Legendary Ocean', 'https://images.ygoprodeck.com/images/cards/295517.jpg', '(This card''s name is always treated as "Umi".)\\r\\nAll WATER monsters on the field gain 200 ATK/DEF. Reduce the Level of all WATER monsters in both players'' hands and on the field by 1.', '0', '0', '0', NULL, NULL, 'Field Spell'),
('32207100', 'A Major Upset', 'https://images.ygoprodeck.com/images/cards/32207100.jpg', 'Tribute 1 face-up Attack Position Level 2 or lower monster you control; return all Level 7 or higher Special Summoned monsters to the hand.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('51351302', 'A Man with Wdjat', 'https://images.ygoprodeck.com/images/cards/51351302.jpg', 'When you Normal Summon this card, and during each of your Standby Phases, select 1 Set card on your opponent''s side of the field. Pick it up and look at it, then return it to its original position.', '4', '1600', '1600', 'DARK', NULL, 'Effect Monster'),
('5728014', 'A Rival Appears!', 'https://images.ygoprodeck.com/images/cards/5728014.jpg', 'Select 1 face-up monster your opponent controls. Special Summon 1 monster from your hand that has the same Level as the selected monster.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('44553392', 'A Shattered, Colorless Realm', 'https://images.ygoprodeck.com/images/cards/44553392.jpg', 'If "Vicious Astraloud" is on the field: Target 1 card on the field; destroy it, then, if the destroyed card''s original name was "Vicious Astraloud", you can Special Summon 1 of your banished "Visas Starfrost", or if it was not, you can make 1 "Vicious Astraloud" you control gain 1500 ATK.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('23587624', 'A Wild Monster Appears!', 'https://images.ygoprodeck.com/images/cards/23587624.jpg', 'If your opponent controls a monster and you control no monsters: Special Summon from your hand, 1 monster with an original Level of 10 or lower that cannot be Normal Summoned/Set, ignoring its Summoning conditions. It is unaffected by the effects of your cards, except for its own effects and this card''s, also shuffle it into the Deck during your opponent''s next End Phase. For the rest of this turn, you cannot Normal Summon/Set or Special Summon monsters, and your opponent takes no damage.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('28596933', 'A Wingbeat of Giant Dragon', 'https://images.ygoprodeck.com/images/cards/28596933.jpg', 'Return 1 Level 5 or higher Dragon-Type monster you control to the hand, and if you do, destroy all Spell and Trap Cards on the field.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('30012506', 'A-Assault Core', 'https://images.ygoprodeck.com/images/cards/30012506.jpg', 'Once per turn, you can either: Target 1 LIGHT Machine monster you control; equip this card to that target, OR: Unequip this card and Special Summon it. A monster equipped with this card is unaffected by your opponent''s monster effects (except its own), also if the equipped monster would be destroyed by battle or card effect, destroy this card instead. If this card is sent from the field to the GY: You can add 1 other Union monster from your GY to your hand.', '4', '1900', '200', 'LIGHT', NULL, 'Union Effect Monster'),
('13026402', 'A-Team: Trap Disposal Unit', 'https://images.ygoprodeck.com/images/cards/13026402.jpg', 'This effect can be used during either player''s turn. When your opponent activates a Trap Card, Tribute this face-up card to negate the activation of the Trap Card and destroy it.', '2', '300', '400', 'FIRE', NULL, 'Effect Monster'),
('75926389', 'A-to-Z Energy Load', 'https://images.ygoprodeck.com/images/cards/75926389.jpg', 'When your opponent activates a card or effect: Draw cards equal to the number of Level 8 or higher LIGHT Machine Fusion Monsters you control. During your Standby Phase: You can banish this card from your GY; shuffle up to 6 of your banished LIGHT Machine monsters into the Deck, including a Union monster. You can only use each effect of "A-to-Z Energy Load" once per turn.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('65172015', 'A-to-Z-Dragon Buster Cannon', 'https://images.ygoprodeck.com/images/cards/65172015.jpg', '"ABC-Dragon Buster" + "XYZ-Dragon Cannon"\\nMust be Special Summoned (from your Extra Deck) by banishing cards you control with the above original names, and cannot be Special Summoned by other ways. (You do not use "Polymerization".) During either player''s turn, when your opponent activates a Spell/Trap Card, or monster effect: You can discard 1 card; negate the activation, and if you do, destroy that card. During either player''s turn: You can banish this card, then target 1 each of your banished "ABC-Dragon Buster", and "XYZ-Dragon Cannon"; Special Summon them.', '10', '4000', '4000', 'LIGHT', NULL, 'Fusion Monster'),
('28645123', 'A.I. Challenge You', 'https://images.ygoprodeck.com/images/cards/28645123.jpg', 'Monsters your opponent controls lose 100 ATK for each card you control. If your "@Ignister" monster battles, your opponent cannot activate cards or effects until the end of the Damage Step. When your "@Ignister" monster is destroyed by battle: You can target 1 other Cyberse monster with 2300 ATK in your GY; Special Summon it. You can only use this effect of "A.I. Challenge You" once per turn.', '0', '0', '0', NULL, NULL, 'Continuous Trap'),
('79015062', 'A.I. Connect', 'https://images.ygoprodeck.com/images/cards/79015062.jpg', 'Reveal 1 Cyberse monster in your hand; apply this effect based on its Attribute, also you cannot Special Summon for the rest of this turn after this card resolves, except Cyberse monsters.\\r\\n● DARK: Special Summon the revealed monster, and if you do, add 1 Level 4 or lower non-DARK Cyberse monster from your Deck to your hand.\\r\\n● Other: Shuffle the revealed monster into the Deck, and if you do, add 1 "@Ignister" monster with a different Attribute from your Deck to your hand.\\r\\nYou can only activate 1 "A.I. Connect" per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('10493654', 'A.I. Contact', 'https://images.ygoprodeck.com/images/cards/10493654.jpg', 'If "Ignister A.I.Land" is in your Field Zone: Reveal 1 "Ignister A.I.Land" in your hand; place it on the bottom of the Deck, and if you do, draw 3 cards. You can only activate 1 "A.I. Contact" per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell');
INSERT INTO card (id, name, img_url, description, level, atk, def, attribute, type, card_type) VALUES
('59332125', 'A.I. Love Fusion', 'https://images.ygoprodeck.com/images/cards/59332125.jpg', 'Fusion Summon 1 Cyberse Fusion Monster from your Extra Deck, using monsters from your hand or field as Fusion Material. If you use your "@Ignister" monster as Fusion Material, you can also use 1 Link Monster your opponent controls as material. You can only activate 1 "A.I. Love Fusion" per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('6552971', 'A.I. Meet You', 'https://images.ygoprodeck.com/images/cards/6552971.jpg', 'Reveal 1 Cyberse monster with 2300 ATK in your hand or Extra Deck, and add 1 "@Ignister" monster with the same Attribute from your Deck to your hand. During the End Phase of this turn, take 2300 damage if you did not Special Summon the revealed monster, or a monster with the same name, after you resolved this effect. You cannot activate monster effects for the rest of this turn after this card resolves, except Cyberse monsters. You can only activate 1 "A.I. Meet You" per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('77421977', 'A.I. Shadow', 'https://images.ygoprodeck.com/images/cards/77421977.jpg', 'Activate this card by targeting 1 "@Ignister" monster you control. That monster gains 800 ATK, also all monsters your opponent controls must attack that monster you control, if able. If this face-up card in its owner''s Spell & Trap Zone has left the field because of an opponent''s effect, and is now in the GY or banished: Draw 1 card. You can only use this effect of "A.I. Shadow" once per turn.', '0', '0', '0', NULL, NULL, 'Continuous Trap'),
('85327820', 'A.I.''s Ritual', 'https://images.ygoprodeck.com/images/cards/85327820.jpg', 'This card can be used to Ritual Summon any Cyberse Ritual Monster. You must also Tribute "@Ignister" monsters from your hand or field whose total Levels equal or exceed the Level of the Ritual Monster you Ritual Summon. If you control an "@Ignister" monster when this effect is activated, you can also use "@Ignister" monster(s) in your GY, by banishing them.', '0', '0', '0', NULL, NULL, 'Ritual Spell'),
('54374642', 'A.I.''s Show', 'https://images.ygoprodeck.com/images/cards/54374642.jpg', 'While you control a Link-3 or higher "@Ignister" monster in the Extra Monster Zone, when an opponent''s monster declares an attack: Special Summon from your Extra Deck any number of non-Link Cyberse monster(s) with 2300 ATK, whose combined ATK is less than or equal to the attacking monster''s ATK, then end the Battle Phase.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('22933016', 'A.I.dle Reborn', 'https://images.ygoprodeck.com/images/cards/22933016.jpg', 'Target 1 "@Ignister" monster in your GY; Special Summon it, also you cannot Special Summon monsters for the rest of this turn after this card resolves, except Cyberse monsters. When an attack is declared involving 2 monsters: You can banish this card from your GY and 1 card from your hand, then target 1 of your "A.I." Spells/Traps that is banished or in your GY, except "A.I.dle Reborn"; add that card to your hand. You can only use each effect of "A.I.dle Reborn" once per turn.', '0', '0', '0', NULL, NULL, 'Quick-Play Spell'),
('69381150', 'A.I.Q', 'https://images.ygoprodeck.com/images/cards/69381150.jpg', 'Activate only if you control an "@Ignister" monster. Once per turn, during your Standby Phase, Tribute 1 Link Monster, or destroy this card. Each player can only Link Summon a monster once per turn while this card is face-up on the field.', '0', '0', '0', NULL, NULL, 'Continuous Trap'),
('96146814', 'A/D Changer', 'https://images.ygoprodeck.com/images/cards/96146814.jpg', 'You can banish this card from your Graveyard, then target 1 monster on the field; change its battle position.', '1', '100', '100', 'LIGHT', NULL, 'Effect Monster'),
('12694768', 'Abaki', 'https://images.ygoprodeck.com/images/cards/12694768.jpg', 'When this card is destroyed and sent to the Graveyard by battle, both players take 500 damage.', '4', '1700', '1100', 'FIRE', NULL, 'Effect Monster'),
('89718302', 'Abare Ushioni', 'https://images.ygoprodeck.com/images/cards/89718302.jpg', 'Once per turn, you can toss a coin and call it. If you call it right, inflict 1000 damage to your opponent. If you call it wrong, you take 1000 damage.', '4', '1200', '1200', 'EARTH', NULL, 'Effect Monster'),
('1561110', 'ABC-Dragon Buster', 'https://images.ygoprodeck.com/images/cards/1561110.jpg', '"A-Assault Core" + "B-Buster Drake" + "C-Crush Wyvern"\\r\\nMust first be Special Summoned (from your Extra Deck) by banishing the above cards you control and/or from your GY. (You do not use "Polymerization".) Once per turn (Quick Effect): You can discard 1 card, then target 1 card on the field; banish it. During your opponent''s turn (Quick Effect): You can Tribute this card, then target 3 of your banished LIGHT Machine Union monsters with different names; Special Summon them.', '8', '3000', '2800', 'LIGHT', NULL, 'Fusion Monster'),
('21846145', 'Abduction', 'https://images.ygoprodeck.com/images/cards/21846145.jpg', 'Target 1 face-up monster your opponent controls; banish 1 monster from your Deck or Extra Deck with the same original Type, Attribute, and Level/Rank/Link Rating, and if you do, take control of that targeted monster, and if you banished a monster with the same original name, that monster''s effects are negated. You can only activate 1 "Abduction" per turn.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('80801743', 'Abominable Chamber of the Unchained', 'https://images.ygoprodeck.com/images/cards/80801743.jpg', 'Special Summon 1 "Unchained" monster from your hand or GY. If this Set card is destroyed by card effect: You can Special Summon 1 "Unchained" monster from your Deck. You can only use each effect of "Abominable Chamber of the Unchained" once per turn.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('1966438', 'Abominable Unchained Soul', 'https://images.ygoprodeck.com/images/cards/1966438.jpg', 'You can only Special Summon "Abominable Unchained Soul(s)" once per turn. If a card(s) you control is destroyed by battle or card effect: You can Special Summon this card from your hand. If this card is Special Summoned: You can discard 1 card; destroy 1 card on the field. Once per turn, during the End Phase, if this card is in the GY because it was destroyed on the field and sent there this turn: You can Special Summon this card, but place it on the bottom of the Deck when it leaves the field.', '8', '3000', '1500', 'DARK', NULL, 'Effect Monster'),
('27412542', 'Abomination''s Prison', 'https://images.ygoprodeck.com/images/cards/27412542.jpg', 'Add 1 "Unchained" card from your Deck to your hand. If this Set card is destroyed by card effect: You can Special Summon 1 "Unchained" monster from your Deck. You can only use each effect of "Abomination''s Prison" once per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('80073414', 'Absolute Axon Kicker', 'https://images.ygoprodeck.com/images/cards/80073414.jpg', '1 Psychic Synchro Monster + 1 Synchro Monster\\r\\nMust first be Fusion Summoned. Cannot be destroyed by card effects. If this card is Fusion Summoned: You can pay 2000 LP; banish all face-up cards your opponent controls. If this card is in your GY, except the turn it was sent there: You can banish it; Special Summon 1 Level 10 Psychic Fusion Monster from your Extra Deck (this is treated as a Fusion Summon). You can only use this effect of "Absolute Axon Kicker" once per turn.', '11', '3400', '2200', 'LIGHT', NULL, 'Fusion Monster'),
('70832512', 'Absolute Crusader', 'https://images.ygoprodeck.com/images/cards/70832512.jpg', 'If a Level 5 or higher monster(s) is Special Summoned: Tribute this face-up card; destroy that Level 5 or higher monster(s).', '4', '1800', '1200', 'EARTH', NULL, 'Effect Monster'),
('60990740', 'Absolute King Back Jack', 'https://images.ygoprodeck.com/images/cards/60990740.jpg', 'During your opponent''s turn (Quick Effect): You can banish this card from the GY; excavate the top card of your Deck, and if it is a Normal Trap, Set it to your field. Otherwise, send it to the GY. That Set card can be activated during this turn. If this card is sent to the GY: You can look at 3 cards from the top of your Deck, then place them on the top of the Deck in any order. You can only use each effect of "Absolute King Back Jack" once per turn.', '1', '0', '0', 'DARK', NULL, 'Effect Monster'),
('51779204', 'Absolute Powerforce', 'https://images.ygoprodeck.com/images/cards/51779204.jpg', 'Target 1 "Red Dragon Archfiend" you control; if it battles an opponent''s monster this turn while you control it, apply these effects until the end of the Damage Step.\\r\\n● It gains 1000 ATK.\\r\\n● Your opponent cannot activate cards or effects.\\r\\n● If it attacks a Defense Position monster, inflict piercing battle damage to your opponent.\\r\\n● Any battle damage your opponent takes from that battle is doubled.', '0', '0', '0', NULL, NULL, 'Quick-Play Spell'),
('71422989', 'Absorb Fusion', 'https://images.ygoprodeck.com/images/cards/71422989.jpg', 'Add 1 "Gem-Knight" card from your Deck to your hand, then you can apply this effect.\\n● Fusion Summon 1 "Gem-Knight" Fusion Monster from your Extra Deck, by banishing Fusion Materials listed on it from your hand or your side of the field.\\nYou can only activate 1 "Absorb Fusion" per turn. You cannot Special Summon monsters the turn you activate this card, except "Gem-Knight" monsters.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('3900605', 'Absorbing Jar', 'https://images.ygoprodeck.com/images/cards/3900605.jpg', 'FLIP: Destroy all Set Spell/Trap Cards on the field, then each player draws 1 card for each of the cards they controlled that was destroyed by this effect. You cannot Set any cards this turn.', '3', '600', '500', 'EARTH', NULL, 'Flip Effect Monster'),
('49771608', 'Absorbing Kid from the Sky', 'https://images.ygoprodeck.com/images/cards/49771608.jpg', 'When this card destroys a monster and sends it to the Graveyard as a result of battle, increase your Life Points by the Level of the destroyed monster x 300 points.', '4', '1300', '1000', 'LIGHT', NULL, 'Effect Monster'),
('67748760', 'Absorouter Dragon', 'https://images.ygoprodeck.com/images/cards/67748760.jpg', 'If you control a "Rokket" monster, you can Special Summon this card (from your hand). You can only Special Summon "Absorouter Dragon" once per turn this way. If this card is sent to the GY: You can add 1 "Rokket" monster from your Deck to your hand. You can only use this effect of "Absorouter Dragon" once per turn.', '7', '1200', '2800', 'DARK', NULL, 'Effect Monster'),
('15308295', 'Abyss Actor - Comic Relief', 'https://images.ygoprodeck.com/images/cards/15308295.jpg', '[ Pendulum Effect ] \\nYou can target 1 "Abyss Actor" Pendulum Monster you control and 1 monster your opponent controls; switch control of both monsters, then destroy this card. You can only use this effect of "Abyss Actor - Comic Relief" once per turn.\\n\\n[ Monster Effect ] \\nYou take no battle damage from attacks involving this card. Once per turn, during your Standby Phase: Give control of this card to your opponent. Once per turn, if control of this face-up card changes: Activate this effect; the owner of this card can destroy 1 Set "Abyss Script" Spell in their Spell & Trap Zone.', '3', '1000', '2000', 'DARK', NULL, 'Pendulum Effect Monster'),
('44179224', 'Abyss Actor - Curtain Raiser', 'https://images.ygoprodeck.com/images/cards/44179224.jpg', '[ Pendulum Effect ] \\nIf you control no monsters: You can Special Summon this card from your Pendulum Zone. You can only use this effect of "Abyss Actor - Curtain Raiser" once per Duel.\\n\\n[ Monster Effect ] \\nGains 1100 ATK if you control no other monsters. Once per turn: You can send 1 "Abyss Script" Spell from your Deck to the GY; add 1 face-up "Abyss Actor" Pendulum Monster from your Extra Deck to your hand.', '4', '1100', '1000', 'DARK', NULL, 'Pendulum Effect Monster'),
('52240819', 'Abyss Actor - Evil Heel', 'https://images.ygoprodeck.com/images/cards/52240819.jpg', '[ Pendulum Effect ] \\nOnce per turn: You can Tribute 1 "Abyss Actor" monster, then target 1 face-up monster your opponent controls; it loses ATK equal to the original ATK of the Tributed monster, until the end of this turn (even if this card leaves the field).\\n\\n[ Monster Effect ] \\nIf this card is Normal or Special Summoned: You can target 1 face-up monster your opponent controls; it loses 1000 ATK for each "Abyss Actor" monster you currently control, until the end of this turn. When this card destroys an opponent''s monster by battle: You can target 1 "Abyss Script" Spell Card in your Graveyard; Set that card.', '8', '3000', '2000', 'DARK', NULL, 'Pendulum Effect Monster'),
('88412339', 'Abyss Actor - Extras', 'https://images.ygoprodeck.com/images/cards/88412339.jpg', '[ Pendulum Effect ] \\nIf your opponent controls a monster: You can Special Summon this card from your Pendulum Zone. You can only use this effect of "Abyss Actor - Extras" once per turn.\\n\\n[ Monster Effect ] \\nYou can Tribute this card; place 1 "Abyss Actor" Pendulum Monster from your Deck in your Pendulum Zone, also for the rest of this turn, you cannot Special Summon monsters, except "Abyss Actor" monsters, nor activate the Pendulum Effect of "Abyss Actor - Extras". You can only use this effect of "Abyss Actor - Extras" once per turn.', '1', '100', '100', 'DARK', NULL, 'Pendulum Effect Monster'),
('99634927', 'Abyss Actor - Funky Comedian', 'https://images.ygoprodeck.com/images/cards/99634927.jpg', '[ Pendulum Effect ] \\nOnce per turn: You can Tribute 1 "Abyss Actor" monster, then target 1 "Abyss Actor" monster you control; it gains ATK equal to the original ATK of the Tributed monster, until the end of this turn (even if this card leaves the field).\\n\\n[ Monster Effect ] \\nIf this card is Normal or Special Summoned: You can make this card gain 300 ATK for each "Abyss Actor" monster you currently control, until the end of this turn. You can target 1 other "Abyss Actor" monster you control; it gains ATK equal to this card''s current ATK, until the end of this turn. This card cannot attack the turn this effect is activated. You can only use this effect of "Abyss Actor - Funky Comedian" once per turn.', '1', '300', '200', 'DARK', NULL, 'Pendulum Effect Monster'),
('2368215', 'Abyss Actor - Hyper Director', 'https://images.ygoprodeck.com/images/cards/2368215.jpg', '1 "Abyss Actor" Pendulum Monster\\r\\nYou can target 1 card in your Pendulum Zone; Special Summon it, then place 1 "Abyss Actor" Pendulum Monster with a different name, from your Deck or face-up Extra Deck, to your Pendulum Zone, also you cannot Normal or Special Summon monsters for the rest of this turn, except "Abyss Actor" monsters. You can only use this effect of "Abyss Actor - Hyper Director" once per turn.', '0', '800', '0', 'DARK', NULL, 'Link Monster'),
('24907044', 'Abyss Actor - Leading Lady', 'https://images.ygoprodeck.com/images/cards/24907044.jpg', '[ Pendulum Effect ] \\nOnce per turn, when you take battle damage from an opponent''s attacking monster: You can activate 1 of these effects; ● That opponent''s monster loses ATK equal to the damage you took (even if this card leaves the field). ● Add 1 face-up "Abyss Actor" Pendulum Monster from your Extra Deck to your hand with ATK less than or equal to the damage you took.\\n\\n[ Monster Effect ] \\nOnce per turn, when battle damage is inflicted: You can target 1 face-up monster your opponent controls; it loses ATK equal to that battle damage. When this card is destroyed by battle, or if this card in its owner''s Monster Zone is destroyed by an opponent''s card effect: You can Set 1 "Abyss Script" Spell directly from your Deck.', '4', '1500', '1000', 'DARK', NULL, 'Pendulum Effect Monster'),
('65477143', 'Abyss Actor - Liberty Dramatist', 'https://images.ygoprodeck.com/images/cards/65477143.jpg', '[ Pendulum Effect ] \\nWhen a monster declares an attack: You can discard 1 card; Special Summon this card to your opponent''s field. You can only use this effect of "Abyss Actor - Liberty Dramatist" once per turn.\\n\\n[ Monster Effect ] \\nIf this card is Special Summoned from the Pendulum Zone: The owner of this card reveals 3 "Abyss Script" Spells from their Deck, their opponent randomly picks 1 for this card''s owner to Set on their field (but the owner destroys it during the End Phase), also shuffle the rest into the Deck. If this card is destroyed: You can shuffle 1 "Abyss Script" Spell from your GY into the Deck. You can only use each effect of "Abyss Actor - Liberty Dramatist" once per turn.', '4', '1500', '1500', 'DARK', NULL, 'Pendulum Effect Monster'),
('78310590', 'Abyss Actor - Mellow Madonna', 'https://images.ygoprodeck.com/images/cards/78310590.jpg', '[ Pendulum Effect ] \\nYou can pay 1000 LP; add 1 "Abyss Actor" Pendulum Monster from your Deck to your hand, except "Abyss Actor - Mellow Madonna", also you cannot Special Summon monsters for the rest of this turn, except "Abyss Actor" Pendulum Monsters (even if this card leaves the field). You can only use this effect of "Abyss Actor - Mellow Madonna" once per turn.\\n\\n[ Monster Effect ] \\nGains 100 ATK for each "Abyss Script" Spell in your GY. You can only use each of the following effects of "Abyss Actor - Mellow Madonna" once per turn.\\r\\n● When a Pendulum Monster you control is destroyed by battle: You can Special Summon this card from your hand.\\r\\n● If an "Abyss Script" Spell Card or effect is activated: You can Special Summon 1 Level 4 or lower "Abyss Actor" Pendulum Monster from your Deck, but return it to the hand during the End Phase.', '7', '1800', '2500', 'DARK', NULL, 'Pendulum Effect Monster'),
('51028231', 'Abyss Actor - Sassy Rookie', 'https://images.ygoprodeck.com/images/cards/51028231.jpg', '[ Pendulum Effect ] \\nIf an "Abyss Actor" monster(s) you control would be destroyed by battle or an opponent''s card effect, you can destroy this card instead.\\n\\n[ Monster Effect ] \\nThe first time this card would be destroyed by battle or card effect each turn, it is not destroyed. If this card is destroyed by battle, or if this card in its owner''s Monster Zone is destroyed by an opponent''s card effect: You can Special Summon 1 Level 4 or lower "Abyss Actor" monster from your Deck, except "Abyss Actor - Sassy Rookie". If this card in the Pendulum Zone is destroyed: You can target 1 Level 4 or lower monster your opponent controls; destroy it.', '4', '1700', '1000', 'DARK', NULL, 'Pendulum Effect Monster'),
('47404795', 'Abyss Actor - Super Producer', 'https://images.ygoprodeck.com/images/cards/47404795.jpg', '2 monsters, including a Fiend monster\\r\\nDuring the Main Phase (Quick Effect): You can target 1 face-up card you control; destroy it, then you can apply 1 of these effects.\\r\\n● Place 1 "Abyss Playhouse - Fantastic Theater" from your Deck, face-up in your Field Zone.\\r\\n● Place 1 "Abyss Actor" Pendulum Monster from your Deck in your Pendulum Zone.\\r\\nYou can only use this effect of "Abyss Actor - Super Producer" once per turn.', '0', '1600', '0', 'DARK', NULL, 'Link Monster'),
('25629622', 'Abyss Actor - Superstar', 'https://images.ygoprodeck.com/images/cards/25629622.jpg', '[ Pendulum Effect ] \\nOnce per turn: You can Tribute 1 "Abyss Actor" monster, then target 1 "Abyss Script" Spell in your GY; add it to your hand.\\n\\n[ Monster Effect ] \\nWhen Normal or Special Summoned, your opponent''s Spell/Trap Cards and effects cannot be activated. Once per turn: You can Set 1 "Abyss Script" Spell directly from your Deck, but it is sent to the GY during the End Phase.', '7', '2500', '1800', 'DARK', NULL, 'Pendulum Effect Monster'),
('39024589', 'Abyss Actor - Trendy Understudy', 'https://images.ygoprodeck.com/images/cards/39024589.jpg', '[ Pendulum Effect ] \\nWhen you Pendulum Summon a monster: You can add 1 face-up Level 1 or 8 "Abyss Actor" Pendulum Monster from your Extra Deck to your hand.\\n\\n[ Monster Effect ] \\nIf you have 2 "Abyss Actor" cards in your Pendulum Zones: You can Tribute this card; Special Summon 1 Level 1 or 8 "Abyss Actor" Pendulum Monster from your hand or face-up from your Extra Deck. You can only use this effect of "Abyss Actor - Trendy Understudy" once per turn.', '2', '700', '700', 'DARK', NULL, 'Pendulum Effect Monster'),
('7279373', 'Abyss Actor - Twinkle Little Star', 'https://images.ygoprodeck.com/images/cards/7279373.jpg', '[ Pendulum Effect ] \\nYou cannot Pendulum Summon monsters, except "Abyss Actor" monsters. This effect cannot be negated. Once per turn: You can target 1 "Abyss Actor" monster you control; this turn, it can make up to 3 attacks on monsters during each Battle Phase, also other monsters you control cannot attack for the rest of this turn (even if this card leaves the field).\\n\\n[ Monster Effect ] \\nCannot be destroyed by battle during your turn. This card can make up to 3 attacks on monsters during each Battle Phase.', '4', '1000', '1000', 'DARK', NULL, 'Pendulum Effect Monster'),
('51391183', 'Abyss Actor - Wild Hope', 'https://images.ygoprodeck.com/images/cards/51391183.jpg', '[ Pendulum Effect ] \\nOnce per turn: You can target 1 "Abyss Actor" card in your other Pendulum Zone; its Pendulum Scale becomes 9 until the end of this turn, also you cannot Special Summon monsters for the rest of this turn, except "Abyss Actor" monsters (even if this card leaves the field).\\n\\n[ Monster Effect ] \\nOnce per turn: You can make this card gain 100 ATK for each "Abyss Actor" monster you currently control with different names, until the end of this turn. If this card is destroyed by battle or card effect: You can add 1 "Abyss Actor" card from your Deck to your hand, except "Abyss Actor - Wild Hope". You can only use this effect of "Abyss Actor - Wild Hope" once per turn.', '4', '1600', '1200', 'DARK', NULL, 'Pendulum Effect Monster'),
('59057953', 'Abyss Actors Back Stage', 'https://images.ygoprodeck.com/images/cards/59057953.jpg', 'If you have 2 "Abyss Actor" cards in your Pendulum Zones: Add 2 "Abyss Actor" Pendulum Monsters with different names from your Deck to your Extra Deck face-up. You can only activate 1 "Abyss Actors Back Stage" per turn.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('4682617', 'Abyss Actors'' Curtain Call', 'https://images.ygoprodeck.com/images/cards/4682617.jpg', 'If an "Abyss Script" Spell Card or effect is activated this turn: Add face-up "Abyss Actor" Pendulum Monsters from your Extra Deck to your hand, up to the number of "Abyss Script" Spells in your GY. Then, you can Special Summon "Abyss Actor" Pendulum Monsters from your hand with different names, up to the number of monsters added to the hand by this effect. You cannot Special Summon monsters for the rest of this turn, except "Abyss Actor" Pendulum Monsters. You can only activate 1 "Abyss Actors'' Curtain Call" per turn.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('6004133', 'Abyss Actors'' Dress Rehearsal', 'https://images.ygoprodeck.com/images/cards/6004133.jpg', 'At the start of your Main Phase 1: Add 1 "Abyss Actor" card and 1 "Abyss Script" Spell from your Deck to your hand. For the rest of this turn after this card resolves, you cannot Pendulum Summon monsters, except "Abyss Actor" monsters.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('21044178', 'Abyss Dweller', 'https://images.ygoprodeck.com/images/cards/21044178.jpg', '2 Level 4 monsters\\nWhile this card has a material attached that was originally WATER, all WATER monsters you control gain 500 ATK. Once per turn (Quick Effect): You can detach 1 material from this card; your opponent cannot activate any card effects in their GY this turn.', '4', '1700', '1400', 'WATER', NULL, 'XYZ Monster'),
('82184400', 'Abyss Keeper', 'https://images.ygoprodeck.com/images/cards/82184400.jpg', '2 WATER monsters\\r\\nCannot be used as Link Material the turn it is Link Summoned. If this card is Link Summoned: You can Special Summon 1 Fish monster from your hand to your zone this card points to. You can target 1 other Fish monster you control and 1 card your opponent controls; banish those cards. You can only use each effect of "Abyss Keeper" once per turn.', '0', '1500', '0', 'WATER', NULL, 'Link Monster'),
('77297908', 'Abyss Playhouse - Fantastic Theater', 'https://images.ygoprodeck.com/images/cards/77297908.jpg', 'You can reveal 1 "Abyss Actor" Pendulum Monster and 1 "Abyss Script" Spell in your hand; add 1 "Abyss Script" Spell from your Deck to your hand, with a different name than that revealed Spell. While you control a Pendulum Summoned "Abyss Actor" Pendulum Monster, any monster effect activated by your opponent becomes "Destroy 1 Set Spell/Trap your opponent controls". You can only use each effect of "Abyss Playhouse - Fantastic Theater" once per turn.', '0', '0', '0', NULL, NULL, 'Field Spell'),
('86578200', 'Abyss Prop - Wild Wagon', 'https://images.ygoprodeck.com/images/cards/86578200.jpg', 'The first time each "Abyss Actor" monster you control would be destroyed by battle each turn, it is not destroyed. Once per turn: You can target 1 "Abyss Actor" monster you control; your opponent cannot target it with card effects until the end of their turn (even if this card leaves the field). If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can return all cards your opponent controls to the hand.', '0', '0', '0', NULL, NULL, 'Continuous Spell'),
('70564929', 'Abyss Script - Abysstainment', 'https://images.ygoprodeck.com/images/cards/70564929.jpg', 'You can Tribute 1 "Abyss Actor" monster, then target 1 "Abyss Script" Spell in your GY; Set it to your field. You can use this effect of "Abyss Script - Abysstainment" up to twice per turn. If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can Special Summon any number of "Abyss Actor" Pendulum Monsters from your Deck.', '0', '0', '0', NULL, NULL, 'Continuous Spell'),
('33503878', 'Abyss Script - Dramatic Story', 'https://images.ygoprodeck.com/images/cards/33503878.jpg', 'Target 1 "Abyss Actor" Pendulum Monster you control; Special Summon 1 "Abyss Actor" monster from your Deck with a different name, then place the targeted monster in your Pendulum Zone or destroy it. If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can return up to 2 cards on the field to the hand. You can only activate 1 "Abyss Script - Dramatic Story" per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('87390798', 'Abyss Script - Fantasy Magic', 'https://images.ygoprodeck.com/images/cards/87390798.jpg', 'Target 1 "Abyss Actor" monster you control; this turn, every monster that battles it, but is not destroyed, returns to the hand at the end of the Damage Step. If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can target 1 card your opponent controls; place it on top of the Deck.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('50179591', 'Abyss Script - Fire Dragon''s Lair', 'https://images.ygoprodeck.com/images/cards/50179591.jpg', 'Target 1 "Abyss Actor" monster you control; if it destroys your opponent''s monster by battle this turn, your opponent banishes 3 monsters from their Extra Deck (their choice). If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can look at your opponent''s Extra Deck, also banish 1 monster from their Extra Deck. You can only use this effect of "Abyss Script - Fire Dragon''s Lair" once per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('23784496', 'Abyss Script - Opening Ceremony', 'https://images.ygoprodeck.com/images/cards/23784496.jpg', 'Gain 500 LP for each "Abyss Actor" monster you control. If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can draw until you have 5 cards in your hand. You can only use each effect of "Abyss Script - Opening Ceremony" once per turn.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('13662809', 'Abyss Script - Rise of the Abyss King', 'https://images.ygoprodeck.com/images/cards/13662809.jpg', 'Target face-up cards on the field, up to the number of Attack Position "Abyss Actor" monsters with different names you control; destroy them. If you control a Level 7 or higher "Abyss Actor" monster, your opponent cannot activate cards or effects in response to this card''s activation. If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can add up to 2 "Abyss Actor" cards and/or "Abyss Script" Spells with different names from your Deck to your hand.', '0', '0', '0', NULL, NULL, 'Normal Spell'),
('41803903', 'Abyss Script - Romantic Terror', 'https://images.ygoprodeck.com/images/cards/41803903.jpg', 'Return 1 "Abyss Actor" Pendulum Monster you control to the hand, and if you do, Special Summon from your Extra Deck in Defense Position, 1 face-up "Abyss Actor" Pendulum Monster with a different original name from that monster. If this Set card in its owner''s control is destroyed by an opponent''s card effect, and you have a face-up "Abyss Actor" Pendulum Monster in your Extra Deck: You can Set any number of "Abyss Script" Spells directly from your Deck. You can only activate 1 "Abyss Script - Romantic Terror" per turn.', '0', '0', '0', NULL, NULL, 'Quick-Play Spell'),
('61496006', 'Abyss Shark', 'https://images.ygoprodeck.com/images/cards/61496006.jpg', 'If this card is used for the Xyz Summon of a "Number" monster, it can be treated as a Level 3 or 4 monster. If all monsters you control are WATER (min. 1): You can Special Summon this card from your hand, and if you do, add 1 Level 3, 4, or 5 Fish monster from your Deck to your hand, except "Abyss Shark". For the rest of this turn, you cannot Special Summon monsters, except WATER monsters, also, double the first battle damage inflicted to your opponent this turn by your "Number" monster battling another monster. You can only use this effect of "Abyss Shark" once per turn.', '5', '1200', '700', 'WATER', NULL, 'Effect Monster'),
('18318842', 'Abyss Soldier', 'https://images.ygoprodeck.com/images/cards/18318842.jpg', 'Once per turn: You can discard 1 WATER monster to the Graveyard to target 1 card on the field; return it to the hand.', '4', '1800', '1300', 'WATER', NULL, 'Effect Monster'),
('97232518', 'Abyss Stungray', 'https://images.ygoprodeck.com/images/cards/97232518.jpg', 'Special Summon this card as an Effect Monster (Thunder-Type/LIGHT/Level 5/ATK 1900/DEF 0). (This card is also still a Trap Card.) If Summoned this way, this card cannot be destroyed by battle.', '0', '0', '0', NULL, NULL, 'Continuous Trap'),
('88409165', 'Abyss Warrior', 'https://images.ygoprodeck.com/images/cards/88409165.jpg', 'Once per turn: You can discard 1 WATER monster to the Graveyard, then target 1 monster in either player''s Graveyard; return that target to either the top or bottom of the Deck.', '4', '1800', '1300', 'WATER', NULL, 'Effect Monster'),
