('84970821', 'Curse of Darkness', 'https://images.ygoprodeck.com/images/cards/84970821.jpg', 'Each time a Spell Card is activated, immediately after it resolves, the player that activated it takes 1000 damage.', '0', '0', '0', NULL, NULL, 'Continuous Trap'),
('64998567', 'Curse of Diabell', 'https://images.ygoprodeck.com/images/cards/64998567.jpg', 'If you control 2 or more "Diabell" monsters: Send 1 monster you control to the GY; destroy all face-up cards your opponent controls. If this card is sent to the GY, or banished, from the hand or Deck: You can add 1 "Diabell" Spell/Trap from your Deck to your hand, except "Curse of Diabell". You can only use each effect of "Curse of Diabell" once per turn.', '0', '0', '0', NULL, NULL, 'Normal Trap'),
('28279543', 'Curse of Dragon', 'https://images.ygoprodeck.com/images/cards/28279543.jpg', 'A wicked dragon that taps into dark forces to execute a powerful attack.', '5', '2000', '1500', 'DARK', NULL, 'Normal Monster'),
