('26669055', 'Sage of Silence', 'https://images.ygoprodeck.com/images/cards/26669055.jpg', 'If this card destroys an opponent''s monster by battle, your opponent cannot activate Spell Cards during the next turn.', '4', '1400', '1000', 'LIGHT', NULL, 'Effect Monster'),
('62054060', 'Sage of Stillness', 'https://images.ygoprodeck.com/images/cards/62054060.jpg', 'If this card destroys an opponent''s monster by battle, your opponent cannot activate Trap Cards during the next turn.', '4', '1400', '1000', 'LIGHT', NULL, 'Effect Monster'),
